#include <bits/stdc++.h>
using namespace std;

void apply_op(vector<int>& p, int x, int y) {
    int n = p.size();
    // [Suffix | Middle | Prefix]
    // Suffix = p[n-y..n-1], Middle = p[x..n-y-1], Prefix = p[0..x-1]
    vector<int> np;
    for (int i = n-y; i < n; i++) np.push_back(p[i]);
    for (int i = x; i < n-y; i++) np.push_back(p[i]);
    for (int i = 0; i < x; i++) np.push_back(p[i]);
    p = np;
}

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    // Place elements 1, 2, ..., n into positions 0, 1, ..., n-1
    for(int target = 0; target < n-2; target++){
        // Find where value (target+1) is
        int pos = -1;
        for(int i = target; i < n; i++) {
            if(p[i] == target+1) { pos = i; break; }
        }
        if(pos == target) continue; // already in place

        // Step 1: Move element from pos to position n-1
        if(pos != n-1) {
            // We want to move p[pos] to the end
            // Use x = pos+1, y = n-1-pos
            // This puts suffix (last n-1-pos elements) at front, prefix (first pos+1 elements) at end
            // Element at pos is last of prefix, goes to position n-1
            int x = pos + 1;
            int y = n - 1 - pos;
            // Need x>0, y>0, x+y<n: x+y = pos+1+n-1-pos = n, NOT < n
            // Middle would be empty. We need x+y < n.
            // Use x = pos, y = n-1-pos if pos > 0
            // Then element at pos: it's at index pos, prefix is p[0..pos-1], middle starts at pos
            // After op: suffix(p[pos+1+..n-1-1+1..no wait p[n-y..n-1]=p[pos+1..n-1]) + middle(p[pos..pos]) + prefix(p[0..pos-1])
            // Element at pos goes to position y = n-1-pos. Not n-1.
            // Alternative: x=pos+1, y=n-2-pos (if n-2-pos>0 i.e. pos<n-2)
            // Then element at pos (last of prefix) goes to end at position n-1
            // x+y = pos+1+n-2-pos = n-1 < n. Good!
            if(pos < n-2) {
                x = pos+1; y = n-2-pos;
                ops.push_back({x,y});
                apply_op(p,x,y);
                // element was at pos (end of prefix), now at end: position n-1
                pos = n-1;
            } else {
                // pos == n-2: use x=1, y=1 to cycle, then retry
                ops.push_back({1,1});
                apply_op(p,1,1);
                for(int i=target;i<n;i++) if(p[i]==target+1){pos=i;break;}
                if(pos!=n-1 && pos<n-2){
                    x=pos+1; y=n-2-pos;
                    ops.push_back({x,y});
                    apply_op(p,x,y);
                    pos=n-1;
                }
            }
        }
        if(pos!=n-1) { /* shouldn't happen but skip */ continue; }
        // Step 2: Move element from n-1 to position target
        // Use x=target, y=1 if target>0: suffix=p[n-1], middle=p[target..n-2], prefix=p[0..target-1]
        // Result: [p[n-1]] + p[target..n-2] + p[0..target-1] => element at position 0, not target
        // Use x=target, y=1: x+y=target+1<n (true if target<n-1)
        // Hmm element goes to pos 0. We want pos=target.
        // Use y=n-target: suffix=p[target..n-1], prefix=p[0..target-1]... but need middle
        // x=target, y=n-target => x+y=n, not <n
        // x=target, y=n-target-1: suffix=p[target+1..n-1], middle=p[target..target], prefix=p[0..target-1]
        // Result: p[target+1..n-1] + [p[target]] + p[0..target-1]. That moves target elem to pos n-1-target... no
        // Let me think differently. Element is at n-1. I want it at target.
        // x=target+1, y=1: suffix=[p[n-1]], middle=p[target+1..n-2], prefix=p[0..target]
        // need target+1+1<n => target<n-2 (true since target<n-2)
        // Result: [p[n-1]] + p[target+1..n-2] + p[0..target]. Element goes to position 0. Not target.
        // Hmm. What if x=1, y=n-1-target?
        // suffix=p[target+1..n-1], middle=p[1..target], prefix=p[0]
        // Result: p[target+1..n-1] + p[1..target] + p[0]
        // Element at n-1 goes to position n-1-target-1. Not right either.
        // Actually I need: after op, p[n-1] ends up at index target.
        // p[n-1] is in suffix if y>=1. It's always last of suffix. Suffix goes to front. So p[n-1] goes to position y-1.
        // So I need y-1 = target => y = target+1.
        // Then x+y < n => x < n-target-1. x>0. So x=1 works if 1+target+1<n => target<n-2.
        if(target < n-2) {
            int x=1, y=target+1;
            ops.push_back({x,y});
            apply_op(p,x,y);
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
